#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    const char *in;
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }
    in = argv[1];
    size_t len = strlen(in);
    if (len > 1024) len = 1024; // limit as observed in binary
    char out[1025]; // buffer for trimmed string
    size_t out_idx = 0;
    bool space_pending = false;

    // Skip leading whitespace
    size_t i = 0;
    while (i < len && isspace((unsigned char)in[i])) {
        i++;
    }

    for (; i < len; ++i) {
        char c = in[i];
        if (isspace((unsigned char)c)) {
            // Remember that we saw whitespace; a single space will be inserted
            // before the next non‑whitespace character (if any).
            space_pending = true;
        } else {
            if (space_pending && out_idx > 0) {
                out[out_idx++] = ' ';
            }
            out[out_idx++] = c;
            space_pending = false;
        }
    }

    // Remove a trailing space that may have been added if the input ended with whitespace.
    if (out_idx > 0 && out[out_idx - 1] == ' ') {
        out_idx--;
    }
    out[out_idx] = '\0';

    if (out_idx == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }
    return 0;
}
